package com.riyadm.smalihelperplus.core.content

import com.google.common.truth.Truth.assertThat
import com.google.common.truth.Truth.assertWithMessage
import com.riyadm.smalihelperplus.domain.model.OpcodeCategory
import kotlinx.serialization.json.Json
import org.junit.BeforeClass
import org.junit.Test
import java.io.File

/**
 * Checks the bundled offline opcode database (generated by tools/content-gen/generate_opcodes.py) against facts from
 * https://source.android.com/docs/core/runtime/dalvik-bytecode, instruction-formats and dex-format.
 */
class BundledOpcodesTest {

    companion object {
        private lateinit var bundle: OpcodeBundleDto
        private lateinit var byName: Map<String, OpcodeDto>

        /** Unit tests normally run with the module directory as working directory; also allow the repo root. */
        private fun locateBundle(): File {
            val candidates = listOf(
                File("src/main/assets/content/opcodes.json"),
                File("app/src/main/assets/content/opcodes.json"),
            )
            return candidates.firstOrNull { it.isFile }
                ?: error("opcodes.json not found; tried ${candidates.map { it.absolutePath }}")
        }

        @JvmStatic
        @BeforeClass
        fun loadBundle() {
            val json = Json { ignoreUnknownKeys = true }
            bundle = json.decodeFromString(OpcodeBundleDto.serializer(), locateBundle().readText())
            byName = bundle.opcodes.associateBy { it.name }
        }

        private val PAYLOADS = mapOf(
            "packed-switch-payload" to 0x0100,
            "sparse-switch-payload" to 0x0200,
            "fill-array-data-payload" to 0x0300,
        )

        /** "(unused)" rows of the spec's bytecode table. */
        private val UNUSED: Set<Int> = ((0x3e..0x43) + 0x73 + (0x79..0x7a) + (0xe3..0xf9)).toSet()

        /** Format ids listed on the instruction-formats page (plus the payload pseudo-formats). */
        private val OFFICIAL_FORMATS = setOf(
            "00x", "10x", "12x", "11n", "11x", "10t", "20t", "20bc", "22x", "21t", "21s", "21h", "21c", "23x",
            "22b", "22t", "22s", "22c", "22cs", "30t", "32x", "31i", "31t", "31c", "35c", "35ms", "35mi", "3rc",
            "3rms", "3rmi", "45cc", "4rcc", "51l",
        ) + PAYLOADS.keys
    }

    private fun op(name: String): OpcodeDto = byName[name] ?: error("missing opcode $name")

    @Test
    fun header_matchesContract() {
        assertThat(bundle.schemaVersion).isEqualTo(CONTENT_SCHEMA_VERSION)
        assertThat(bundle.contentVersion).isEqualTo(1)
        assertThat(bundle.generatedAt).isEqualTo("2026-10-30")
    }

    @Test
    fun bundle_passesContentValidator() {
        val result = ContentValidator.validateOpcodes(bundle)
        if (result is ContentValidator.Result.Invalid) {
            throw AssertionError("ContentValidator rejected the bundle:\n" + result.errors.joinToString("\n"))
        }
        assertThat(result).isEqualTo(ContentValidator.Result.Valid)
    }

    @Test
    fun bundle_coversEveryUsedOpcodeExactlyOnce_plusThreePayloads() {
        assertThat(bundle.opcodes).hasSize(227)
        assertThat(byName).hasSize(bundle.opcodes.size)

        val instructionValues = bundle.opcodes.filter { it.name !in PAYLOADS }.map { it.opcode }
        assertThat(instructionValues).containsNoDuplicates()
        assertThat(instructionValues.toSet()).isEqualTo((0x00..0xff).toSet() - UNUSED)

        PAYLOADS.forEach { (name, ident) ->
            val p = op(name)
            assertThat(p.opcode).isEqualTo(ident)
            assertThat(p.format).isEqualTo(name)
            assertThat(p.category).isEqualTo(OpcodeCategory.ADVANCED.id)
        }
    }

    @Test
    fun bundle_excludesUnusedAndOdexOnlyOpcodes() {
        val odexMarkers = listOf("-quick", "-volatile", "execute-inline", "invoke-direct-empty", "invoke-object-init",
            "return-void-barrier", "return-void-no-barrier", "throw-verification-error")
        bundle.opcodes.forEach { o ->
            assertWithMessage(o.name).that(odexMarkers.none { o.name.contains(it) }).isTrue()
        }
        assertThat(bundle.opcodes.map { it.opcode }.filter { it in UNUSED }).isEmpty()
    }

