    @Test
    fun versionGating_matchesDexFormatNotes() {
        // dex 038 = Android 8.0 (API 26); dex 039 = Android 9 (API 28).
        val gated = mapOf(
            "invoke-polymorphic" to (26 to "038"),
            "invoke-polymorphic/range" to (26 to "038"),
            "invoke-custom" to (26 to "038"),
            "invoke-custom/range" to (26 to "038"),
            "const-method-handle" to (28 to "039"),
            "const-method-type" to (28 to "039"),
        )
        bundle.opcodes.forEach { o ->
            val (api, dex) = gated[o.name] ?: (1 to "035")
            assertWithMessage("${o.name} minApi").that(o.minApi).isEqualTo(api)
            assertWithMessage("${o.name} dexVersion").that(o.dexVersion).isEqualTo(dex)
        }
        assertThat(op("invoke-polymorphic").compatibility).contains("MethodHandle.invokeExact")
        assertThat(op("invoke-polymorphic").compatibility).contains("VarHandle")
        assertThat(op("invoke-super").compatibility).contains("037")
    }

    @Test
    fun categoryCounts_areStable() {
        val counts = bundle.opcodes.groupingBy { it.category }.eachCount()
        val expected = mapOf(
            "move" to 12, "return" to 4, "constant" to 11, "monitor" to 2, "type" to 2, "object" to 1,
            "array" to 19, "field" to 28, "invoke" to 10, "arithmetic" to 54, "bitwise" to 35, "comparison" to 5,
            "branch" to 12, "jump" to 3, "switch" to 2, "conversion" to 15, "exception" to 2,
            "method_handle" to 6, "advanced" to 4,
        )
        assertThat(counts).isEqualTo(expected)
        assertThat(expected.keys).isEqualTo(OpcodeCategory.entries.map { it.id }.toSet())
        assertThat(op("move-exception").category).isEqualTo("exception")
        assertThat(op("neg-int").category).isEqualTo("arithmetic")
        assertThat(op("not-long").category).isEqualTo("bitwise")
        assertThat(op("shl-int/lit8").category).isEqualTo("bitwise")
        assertThat(op("rsub-int").category).isEqualTo("arithmetic")
    }

    @Test
    fun everyEntry_isComplete() {
        bundle.opcodes.forEach { o ->
            assertWithMessage("${o.name} format").that(o.format).isIn(OFFICIAL_FORMATS)
            listOf(o.syntax, o.summary, o.description, o.technical, o.example, o.exampleExplanation,
                o.registerUsage, o.compatibility).forEach { assertWithMessage(o.name).that(it).isNotEmpty() }
            assertWithMessage("${o.name} summary is one line").that(o.summary).doesNotContain("\n")
            assertWithMessage("${o.name} syntax starts with mnemonic").that(o.syntax).startsWith(
                if (o.name in PAYLOADS) "." else o.name,
            )
            assertWithMessage("${o.name} mistakes").that(o.commonMistakes.size).isIn(2..4)
            assertWithMessage("${o.name} tags").that(o.tags).isNotEmpty()
            if (o.format != "10x" && o.name !in PAYLOADS) {
                assertWithMessage("${o.name} operands").that(o.operands).isNotEmpty()
            }
            o.related.forEach { assertWithMessage("${o.name} related").that(byName).containsKey(it) }
            assertWithMessage("${o.name} related").that(o.related).isNotEmpty()
            assertWithMessage("${o.name} cites the bytecode page").that(
                o.references.any { it.url.startsWith("https://source.android.com/docs/core/runtime/dalvik-bytecode") },
            ).isTrue()
            o.references.forEach { assertWithMessage(o.name).that(it.url).startsWith("https://") }
        }
    }

    @Test
    fun smaliSyntax_usesSmaliMnemonicsAndReferences() {
        assertThat(op("invoke-virtual").syntax).isEqualTo("invoke-virtual {vC, vD, vE, vF, vG}, Lclass;->method(params)ret")
        assertThat(op("invoke-virtual/range").syntax).startsWith("invoke-virtual/range {vCCCC .. vNNNN}, ")
        assertThat(op("iget").syntax).isEqualTo("iget vA, vB, Lclass;->name:Type")
        assertThat(op("sget-object").syntax).isEqualTo("sget-object vAA, Lclass;->name:Type")
        assertThat(op("rsub-int").syntax).isEqualTo("rsub-int vA, vB, lit16")
        assertThat(op("rsub-int/lit8").syntax).isEqualTo("rsub-int/lit8 vAA, vBB, lit8")
        assertThat(op("const-string/jumbo").syntax).startsWith("const-string/jumbo vAA, \"")
        assertThat(op("if-eqz").syntax).isEqualTo("if-eqz vAA, :label")
        assertThat(op("move-wide/from16").syntax).isEqualTo("move-wide/from16 vAA, vBBBB")
    }

    @Test
    fun technicalText_reflectsSpecSemantics() {
        // Only integer div/rem throw ArithmeticException.
        listOf("div-int", "rem-int", "div-long/2addr", "rem-long", "div-int/lit16", "rem-int/lit8").forEach {
            assertWithMessage(it).that(op(it).technical).contains("ArithmeticException")
        }
        listOf("div-float", "rem-double", "div-double/2addr", "add-int", "mul-long").forEach {
            assertWithMessage(it).that(op(it).technical).doesNotContain("Throws java.lang.ArithmeticException")
        }
        assertThat(op("shl-int").technical).contains("0x1f")
        assertThat(op("ushr-int/lit8").technical).contains("0x1f")
        assertThat(op("shr-long").technical).contains("0x3f")
        assertThat(op("shl-long/2addr").technical).contains("single 32-bit register")
        assertThat(op("cmpl-float").technical).contains("the result is -1")
        assertThat(op("cmpg-double").technical).contains("the result is 1")
        assertThat(op("float-to-int").technical).contains("NaN")
        assertThat(op("double-to-long").technical).contains("0x7fffffffffffffff")
        assertThat(op("int-to-char").technical).contains("without sign extension")
        assertThat(op("rsub-int").technical).contains("lit16 - vB")
        assertThat(op("move-wide").technical).contains("overlapping")
        assertThat(op("const/4").operands.last().description).contains("-8..7")
        assertThat(op("const-wide/high16").technical).contains("<< 48")
        assertThat(op("aput-object").technical).contains("ArrayStoreException")
        assertThat(op("goto/32").technical).contains("may be 0")
        assertThat(op("packed-switch-payload").technical).contains("(size * 2) + 4")
        assertThat(op("sparse-switch-payload").technical).contains("(size * 4) + 2")
        assertThat(op("fill-array-data-payload").technical).contains("(size * element_width + 1) / 2 + 4")
    }

    @Test
    fun equivalents_presentWhereMeaningful() {
        assertThat(op("nop").javaEquivalent).isNull()
        PAYLOADS.keys.forEach { assertThat(op(it).javaEquivalent).isNull() }
        assertThat(op("add-int").javaEquivalent).isEqualTo("int r = a + b;")
        assertThat(op("ushr-long").kotlinEquivalent).isEqualTo("val r = a ushr b")
        assertThat(op("instance-of").kotlinEquivalent).contains("is String")
        val withJava = bundle.opcodes.count { it.javaEquivalent != null }
        assertThat(withJava).isAtLeast(220)
    }
}
